use std::collections::{HashMap, HashSet};

struct Solution;

impl Solution {
    pub fn is_solvable(words: Vec<String>, result: String) -> bool {
        // Collect all unique characters
        let mut chars = Vec::new();
        let mut char_set = HashSet::new();
        for w in &words {
            for &b in w.as_bytes() {
                let c = b as char;
                if !char_set.contains(&c) {
                    char_set.insert(c);
                    chars.push(c);
                }
            }
        }
        for &b in result.as_bytes() {
            let c = b as char;
            if !char_set.contains(&c) {
                char_set.insert(c);
                chars.push(c);
            }
        }
        if chars.len() > 10 {
            return false; // more than 10 distinct chars, impossible to assign digits
        }

        // Leading characters cannot be zero
        let mut leading_chars = HashSet::new();
        for w in &words {
            if let Some(&b) = w.as_bytes().first() {
                leading_chars.insert(b as char);
            }
        }
        if let Some(&b) = result.as_bytes().first() {
            leading_chars.insert(b as char);
        }

        // Map from char to index in chars vector
        let mut char_to_index = HashMap::new();
        for (i, &c) in chars.iter().enumerate() {
            char_to_index.insert(c, i);
        }

        // Precompute the contribution of each character in the sum:
        // sum of words digits - result digits = 0
        // We will store the coefficient for each character:
        // For each position (from right to left), add +1 for words, -1 for result
        // For example, SEND + MORE = MONEY
        // S: 1000 + 0 - 0, M: 0 + 1000 - 10000, etc.
        let mut coeffs = vec![0i32; chars.len()];

        // Helper to add coefficients for a word with sign (+1 for words, -1 for result)
        let add_word_coeffs = |word: &str, sign: i32, coeffs: &mut Vec<i32>, char_to_index: &HashMap<char, usize>| {
            let bytes = word.as_bytes();
            let len = bytes.len();
            for (i, &b) in bytes.iter().enumerate() {
                let c = b as char;
                let idx = char_to_index[&c];
                coeffs[idx] += sign * 10_i32.pow((len - 1 - i) as u32);
            }
        };

        for w in &words {
            add_word_coeffs(w, 1, &mut coeffs, &char_to_index);
        }
        add_word_coeffs(&result, -1, &mut coeffs, &char_to_index);

        // Backtracking to assign digits to chars
        let mut used = vec![false; 10];
        let mut assignment = vec![-1; chars.len()];

        fn backtrack(
            pos: usize,
            chars: &Vec<char>,
            coeffs: &Vec<i32>,
            used: &mut Vec<bool>,
            assignment: &mut Vec<i32>,
            leading_chars: &HashSet<char>,
            char_to_index: &HashMap<char, usize>,
        ) -> bool {
            if pos == chars.len() {
                // Check if sum is zero
                let mut sum = 0i64;
                for i in 0..chars.len() {
                    sum += coeffs[i] as i64 * assignment[i] as i64;
                }
                return sum == 0;
            }

            let c = chars[pos];
            for d in 0..10 {
                if used[d] {
                    continue;
                }
                // Leading char cannot be zero
                if d == 0 && leading_chars.contains(&c) {
                    continue;
                }
                assignment[pos] = d as i32;
                used[d] = true;
                if backtrack(pos + 1, chars, coeffs, used, assignment, leading_chars, char_to_index) {
                    return true;
                }
                used[d] = false;
                assignment[pos] = -1;
            }
            false
        }

        backtrack(0, &chars, &coeffs, &mut used, &mut assignment, &leading_chars, &char_to_index)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_examples() {
        assert_eq!(
            Solution::is_solvable(vec!["SEND".to_string(), "MORE".to_string()], "MONEY".to_string()),
            true
        );
        assert_eq!(
            Solution::is_solvable(
                vec!["SIX".to_string(), "SEVEN".to_string(), "SEVEN".to_string()],
                "TWENTY".to_string()
            ),
            true
        );
        assert_eq!(
            Solution::is_solvable(vec!["LEET".to_string(), "CODE".to_string()], "POINT".to_string()),
            false
        );
    }
}

